CREATE TABLE IF NOT EXISTS incidents (incident_id TEXT PRIMARY KEY, detected_at TIMESTAMPTZ NOT NULL, resolved_at TIMESTAMPTZ, severity TEXT NOT NULL, affected_table TEXT NOT NULL, incident_type TEXT NOT NULL, symptoms TEXT NOT NULL, root_cause TEXT, resolution TEXT, status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incident_fixes (fix_id TEXT PRIMARY KEY, incident_id TEXT NOT NULL, root_cause TEXT, sql_patch TEXT, python_patch TEXT, verification_result JSONB, approved BOOLEAN DEFAULT FALSE, deployment_status TEXT);
CREATE TABLE IF NOT EXISTS agent_executions (execution_id TEXT PRIMARY KEY, incident_id TEXT, workflow_id TEXT, agent_name TEXT, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, status TEXT, input_summary TEXT, output_summary TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS approvals (approval_id TEXT PRIMARY KEY, incident_id TEXT, fix_id TEXT, requested_at TIMESTAMPTZ, approved_at TIMESTAMPTZ, reviewer TEXT, decision TEXT, reason TEXT);
CREATE TABLE IF NOT EXISTS deployments (deployment_id TEXT PRIMARY KEY, incident_id TEXT, fix_id TEXT, environment TEXT, started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, status TEXT, rollback_available BOOLEAN, rollback_status TEXT);
CREATE TABLE IF NOT EXISTS risk_assessments (risk_id TEXT PRIMARY KEY, incident_id TEXT, fix_id TEXT, score INTEGER, level TEXT, reasons JSONB, created_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_logs (audit_id TEXT PRIMARY KEY, incident_id TEXT, actor TEXT, action TEXT, target TEXT, timestamp TIMESTAMPTZ, result TEXT, metadata JSONB);
CREATE TABLE IF NOT EXISTS pipeline_metadata (pipeline_id TEXT PRIMARY KEY, pipeline_name TEXT, source_system TEXT, source_table TEXT, target_table TEXT, schedule TEXT, owner TEXT, pipeline_type TEXT, last_run_at TIMESTAMPTZ, status TEXT, average_runtime_seconds NUMERIC);
CREATE TABLE IF NOT EXISTS data_lineage (lineage_id TEXT PRIMARY KEY, source_table TEXT, target_table TEXT, transformation_name TEXT, pipeline_id TEXT, dependency_type TEXT);
CREATE TABLE IF NOT EXISTS schema_history (schema_version_id TEXT PRIMARY KEY, table_name TEXT, column_name TEXT, data_type TEXT, is_nullable TEXT, recorded_at TIMESTAMPTZ, change_type TEXT, previous_column_name TEXT);
CREATE TABLE IF NOT EXISTS pipeline_logs (log_id TEXT PRIMARY KEY, pipeline_id TEXT, execution_id TEXT, started_at TIMESTAMPTZ, ended_at TIMESTAMPTZ, status TEXT, rows_read INTEGER, rows_written INTEGER, error_type TEXT, error_message TEXT);
